def get_city_to_airport(city: str, airport_code: str) -> Optional[GroundTransport]:
    """获取城市市区到机场的交通信息"""
    city_data = CITY_TO_AIRPORT.get(city)
    if city_data:
        return city_data.get(airport_code)
    return None


def get_airport_to_city(airport_code: str, city: str) -> Optional[GroundTransport]:
    """获取机场到城市市区的交通信息"""
    airport_data = AIRPORT_TO_CITY.get(airport_code)
    if airport_data:
        return airport_data.get(city)
    return None


def estimate_ground_transport(
    from_city: str,
    to_airport_code: str,
    is_departure: bool = True
) -> GroundTransport:
    """
    估算地面交通成本

    Args:
        from_city: 城市名
        to_airport_code: 机场代码
        is_departure: True=出发地到机场, False=机场到目的地

    Returns:
        GroundTransport对象
    """
    if is_departure:
        # 出发地市区 → 起飞机场
        transport = get_city_to_airport(from_city, to_airport_code)
        if transport:
            return transport
        # 未找到数据，使用默认估算
        return GroundTransport(
            from_location=f"{from_city}市区",
            to_location=f"{to_airport_code}机场",
            transport_type="机场大巴",
            distance_km=30,
            duration_minutes=45,
            cost_yuan=25,
            note="估算值"
        )
    else:
        # 到达机场 → 目的地市区
        transport = get_airport_to_city(to_airport_code, from_city)
        if transport:
            return transport
        # 未找到数据，使用默认估算
        return GroundTransport(
            from_location=f"{to_airport_code}机场",
            to_location=f"{from_city}市区",
            transport_type="机场大巴",
            distance_km=30,
            duration_minutes=45,
            cost_yuan=25,
            note="估算值"
        )


def calculate_total_journey(
    departure_city: str,
    departure_airport_code: str,
    arrival_airport_code: str,
    destination_city: str,
    flight_price: float,
    flight_duration_minutes: int = 120,
) -> dict:
    """
    计算完整行程的总成本和总耗时

    Returns:
        dict: 包含各段交通信息和总成本
    """
    # 出发地市区 → 起飞机场
    to_airport = estimate_ground_transport(departure_city, departure_airport_code, is_departure=True)

    # 到达机场 → 目的地市区
    from_airport = estimate_ground_transport(destination_city, arrival_airport_code, is_departure=False)

    # 计算总成本和总耗时
    ground_cost = to_airport.cost_yuan + from_airport.cost_yuan
    ground_duration = to_airport.duration_minutes + from_airport.duration_minutes
    total_cost = ground_cost + flight_price
    total_duration = ground_duration + flight_duration_minutes + 90  # 加90分钟候机时间

    return {
        "to_airport": to_airport.to_dict(),
        "flight": {
            "from": departure_airport_code,
            "to": arrival_airport_code,
            "price": flight_price,
            "duration_minutes": flight_duration_minutes,
        },
        "from_airport": from_airport.to_dict(),
        "summary": {
            "ground_cost": ground_cost,
            "flight_cost": flight_price,
            "total_cost": total_cost,
            "ground_duration_minutes": ground_duration,
            "flight_duration_minutes": flight_duration_minutes,
            "total_duration_minutes": total_duration,
            "total_duration_hours": round(total_duration / 60, 1),
        }
    }


def format_journey_plan(plan: dict) -> str:
    """格式化行程规划为可读文本"""
    lines = []
    lines.append("=" * 50)
    lines.append("行程规划")
    lines.append("=" * 50)

    # 第一段：市区到机场
    to_airport = plan["to_airport"]
    lines.append(f"\n📍 第1段：{to_airport['from']} → {to_airport['to']}")
    lines.append(f"   交通：{to_airport['type']}")
    lines.append(f"   耗时：{to_airport['duration_minutes']}分钟")
    lines.append(f"   费用：¥{to_airport['cost_yuan']}")

    # 第二段：航班
    flight = plan["flight"]
    lines.append(f"\n✈️ 第2段：{flight['from']} → {flight['to']}")
    lines.append(f"   价格：¥{flight['price']}")
    lines.append(f"   飞行时间：{flight['duration_minutes']}分钟")

    # 第三段：机场到市区
    from_airport = plan["from_airport"]
    lines.append(f"\n📍 第3段：{from_airport['from']} → {from_airport['to']}")
    lines.append(f"   交通：{from_airport['type']}")
    lines.append(f"   耗时：{from_airport['duration_minutes']}分钟")
    lines.append(f"   费用：¥{from_airport['cost_yuan']}")

    # 汇总
    summary = plan["summary"]
    lines.append("\n" + "-" * 50)
    lines.append("📊 行程汇总")
    lines.append(f"   地面交通费用：¥{summary['ground_cost']}")
    lines.append(f"   机票费用：¥{summary['flight_cost']}")
    lines.append(f"   总费用：¥{summary['total_cost']}")
    lines.append(f"   总耗时：约{summary['total_duration_hours']}小时")

    return "\n".join(lines)

"""机票搜索平台处理器

支持四个平台：
- qunar: 去哪儿
- ctrip: 携程
- fliggy: 飞猪
- ly: 同程
"""

from __future__ import annotations

import json
import logging
import os
import re
import time
from abc import ABC, abstractmethod
from typing import Optional

logger = logging.getLogger("flight-search")

# 调试模式：保存页面HTML用于分析
DEBUG_SAVE_HTML = os.environ.get("DEBUG_SAVE_HTML", "").lower() in ("1", "true", "yes")


class PlatformHandler(ABC):
    """平台处理器基类"""

    name: str = ""
    url: str = ""
    login_url: str = ""
    cookie_domain: str = ""  # Cookie 作用域名，子类需要设置

    @abstractmethod
    def search(
        self, page, departure_city: str, arrival_city: str, date: str
    ) -> list[dict]:
        """搜索航班

        Args:
            page: CDP Page 对象
            departure_city: 出发城市
            arrival_city: 到达城市
            date: 日期 (YYYY-MM-DD)

        Returns:
            航班列表
        """
        pass

    def search_without_navigation(
        self, page, departure_city: str, arrival_city: str, date: str
    ) -> list[dict]:
        """在已导航的页面上搜索（跳过页面导航）

        子类可重写此方法以优化重复搜索。
        """
        return self.search(page, departure_city, arrival_city, date)

    def check_login(self, page) -> bool:
        """检查登录状态

        Returns:
            True 已登录，False 未登录
        """
        # 默认实现：检查是否有登录按钮
        try:
            login_btn = page.evaluate(
                "document.querySelector('.login-btn, .login-btn-pc, #login-btn') !== null"
            )
            return not login_btn
        except Exception:
            return False

    def _load_cookies_from_file(self, page) -> bool:
        """从本地文件加载 cookie 到浏览器
        
        Args:
            page: CDP Page 对象
            
        Returns:
            True 加载成功，False 加载失败或文件不存在
        """
        if not self.cookie_domain:
            logger.debug(f"未设置 cookie_domain，跳过 cookie 加载")
            return False
            
        # cookie 文件路径
        cookie_dir = os.path.join(os.path.expanduser("~"), ".qvxian")
        cookie_file = os.path.join(cookie_dir, f"{self.cookie_domain.split('.')[0]}_cookies.json")
        
        if not os.path.exists(cookie_file):
            logger.debug(f"Cookie 文件不存在: {cookie_file}")
            return False
        
        try:
            with open(cookie_file, 'r', encoding='utf-8') as f:
                cookie_data = json.load(f)
            
            cookies = cookie_data.get("cookies", {})
            if not cookies:
                logger.warning("Cookie 文件中没有有效的 cookie")
                return False
            
            # 先导航到目标域名（设置 cookie 需要在同域下）
            current_url = page.evaluate("window.location.href")
            if self.cookie_domain not in current_url:
                page.navigate(self.url)
                time.sleep(1)
            
            # 使用 CDP Network.setCookie 设置 cookie（支持特殊字符）
            success_count = 0
            for name, value in cookies.items():
                try:
                    if page.set_cookie(name, value, f".{self.cookie_domain}"):
                        success_count += 1
                except Exception as e:
                    logger.debug(f"设置 cookie {name} 失败: {e}")
            
            logger.info(f"已从本地加载 {success_count}/{len(cookies)} 个 cookie")
            time.sleep(0.5)
            return success_count > 0
            
        except Exception as e:
            logger.warning(f"加载 cookie 文件失败: {e}")
            return False


class QunarHandler(PlatformHandler):
    """去哪儿平台处理器"""

    name = "去哪儿"
    url = "https://flight.qunar.com/"
    login_url = "https://user.qunar.com/passport/login.jsp"
    cookie_domain = "qunar.com"

    def search(
        self, page, departure_city: str, arrival_city: str, date: str
    ) -> list[dict]:
        """搜索去哪儿航班"""
        # 尝试自动加载 cookie
        logger.info("尝试加载本地 cookie...")
        self._load_cookies_from_file(page)
        
        # 检查登录状态
        logger.info("检查登录状态...")
        if not self.check_login(page):
            logger.error("未登录！请先保存 cookie：\n1. 在 Chrome 中手动登录去哪儿\n2. 运行: qvxian flight-save-cookie --platform qunar")
            return [{
                "error": "未登录",
                "message": "请先登录去哪儿账号才能搜索航班。推荐使用 cookie 登录：\n1. 启动 Chrome: python -m qvxianjiuguo.chrome_launcher\n2. 在 Chrome 中手动登录去哪儿\n3. 保存 cookie: qvxian flight-save-cookie --platform qunar",
                "login_required": True
            }]
        
        # 尝试直接导航到搜索结果页面（更可靠）
        # 构建搜索URL
        search_url = f"https://flight.qunar.com/site/oneway_list.htm?searchDepartureAirport={departure_city}&searchArrivalAirport={arrival_city}&searchDepartureTime={date}"
        logger.info(f"直接导航到搜索页面: {search_url}")
        
        try:
            page.navigate(search_url)
            page.wait_for_load()
            
            # 智能等待航班元素加载
            max_wait = 10  # 最多等待10秒
            for i in range(max_wait):
                time.sleep(1)
                # 检查是否有航班元素
                has_flights = page.evaluate(
                    """(() => {
                        const selectors = ['.b-airfly', '.m-airfly-lst', '.flight-item', '.e-airfly', '[class*="airfly"]'];
                        for (const sel of selectors) {
                            if (document.querySelector(sel)) return true;
                        }
                        // 检查页面内容长度
                        return document.body.innerHTML.length > 200000;
                    })()"""
                )
                if has_flights:
                    logger.info(f"航班元素已加载（等待 {i+1}s）")
                    break
            
            # 额外等待确保数据稳定
            time.sleep(2)
            
            # 检查是否成功导航
            current_url = page.evaluate("window.location.href")
            if "oneway_list" in current_url:
                logger.info("成功导航到搜索结果页面")
                return self._parse_results(page)
        except Exception as e:
            logger.warning(f"直接导航失败: {e}，尝试传统搜索方式")
        
        # 回退到传统搜索方式
        page.navigate(self.url)
        page.wait_for_load()
        time.sleep(2)

        return self._do_search(page, departure_city, arrival_city, date)

    def search_without_navigation(
        self, page, departure_city: str, arrival_city: str, date: str
    ) -> list[dict]:
        """在已导航的页面上搜索"""
        return self._do_search(page, departure_city, arrival_city, date)

    def _do_search(
        self, page, departure_city: str, arrival_city: str, date: str
    ) -> list[dict]:
        """执行搜索"""
        logger.info(f"开始搜索: {departure_city} -> {arrival_city}, 日期: {date}")
        
        # 0. 清除可能的反爬虫覆盖层和弹窗
        try:
            page.evaluate(
                """(() => {
                    // 移除可能的覆盖层
                    const overlays = document.querySelectorAll('[style*="pointer-events: none"], [style*="z-index: 2147483647"]');
                    overlays.forEach(el => el.remove());
                    
                    // 点击关闭可能的弹窗
                    const closeBtns = document.querySelectorAll('.close-btn, .close, [class*="close"], .modal-close, .dialog-close');
                    closeBtns.forEach(btn => {
                        try { btn.click(); } catch(e) {}
                    });
                    
                    // 移除可能的遮罩层
                    const masks = document.querySelectorAll('[class*="mask"], [class*="overlay"], [class*="modal-backdrop"]');
                    masks.forEach(el => el.remove());
                    
                    return true;
                })()"""
            )
            time.sleep(0.5)
        except Exception:
            pass
        
        # 1. 选择单程（如果需要）
        try:
            page.evaluate(
                """(() => {
                    const singleBtn = document.querySelector('#searchTypeSng, .js-searchtype-oneway');
                    if (singleBtn && !singleBtn.checked) {
                        singleBtn.click();
                    }
                })()"""
            )
            time.sleep(0.3)
        except Exception as e:
            logger.debug(f"选择单程失败（可能已选中）: {e}")

        # 2. 输入出发城市
        logger.info(f"输入出发城市: {departure_city}")
        try:
            # 点击出发城市输入框
            page.evaluate(
                """(() => {
                    const selectors = [
                        'input[name="fromCity"]',
                        '.textbox[name="fromCity"]',
                        '.qcbox.qcity',
                        '.js-fromcity'
                    ];
                    for (const sel of selectors) {
                        const el = document.querySelector(sel);
                        if (el) {
                            el.click();
                            el.focus();
                            return true;
                        }
                    }
                    return false;
                })()"""
            )
            time.sleep(0.5)
            
            # 输入城市名
            page.evaluate(
                f"""(() => {{
                    const activeEl = document.activeElement;
                    if (activeEl) {{
                        activeEl.value = {json.dumps(departure_city)};
                        activeEl.dispatchEvent(new Event('input', {{ bubbles: true }}));
                        activeEl.dispatchEvent(new Event('change', {{ bubbles: true }}));
                    }}
                    
                    // 也尝试直接设置输入框
                    const inputs = document.querySelectorAll('input[name="fromCity"], .textbox[name="fromCity"]');
                    inputs.forEach(el => {{
                        el.value = {json.dumps(departure_city)};
                        el.dispatchEvent(new Event('input', {{ bubbles: true }}));
                    }});
                }})()"""
            )
            time.sleep(0.8)
            
            # 选择下拉选项
            page.evaluate(
                """(() => {
                    const selectors = [
                        '.city-suggest li',
                        '.qcbox-city-list li',
                        '.js-citylist li',
                        '.suggest-item',
                        '[data-city]'
                    ];
                    for (const sel of selectors) {
                        const items = document.querySelectorAll(sel);
                        if (items.length > 0) {
                            items[0].click();
                            return true;
                        }
                    }
                    return false;
                })()"""
            )
            time.sleep(0.3)
            
            # 发送 ESC 键关闭下拉框
            try:
                page.press_key("Escape")
            except Exception:
                pass
            time.sleep(0.3)
        except Exception as e:
            logger.warning(f"输入出发城市失败: {e}")

        # 3. 输入到达城市
        logger.info(f"输入到达城市: {arrival_city}")
        try:
            page.evaluate(
                """(() => {
                    const selectors = [
                        'input[name="toCity"]',
                        '.textbox[name="toCity"]',
                        '.qcbox.qcity:last-of-type',
                        '.js-tocity'
                    ];
                    for (const sel of selectors) {
                        const el = document.querySelector(sel);
                        if (el) {
                            el.click();
                            el.focus();
                            return true;
                        }
                    }
                    return false;
                })()"""
            )
            time.sleep(0.5)
            
            page.evaluate(
                f"""(() => {{
                    const activeEl = document.activeElement;
                    if (activeEl) {{
                        activeEl.value = {json.dumps(arrival_city)};
                        activeEl.dispatchEvent(new Event('input', {{ bubbles: true }}));
                        activeEl.dispatchEvent(new Event('change', {{ bubbles: true }}));
                    }}
                    
                    const inputs = document.querySelectorAll('input[name="toCity"], .textbox[name="toCity"]');
                    inputs.forEach(el => {{
                        el.value = {json.dumps(arrival_city)};
                        el.dispatchEvent(new Event('input', {{ bubbles: true }}));
                    }});
                }})()"""
            )
            time.sleep(0.8)
            
            # 选择下拉选项
            page.evaluate(
                """(() => {
                    const selectors = [
                        '.city-suggest li',
                        '.qcbox-city-list li',
                        '.js-citylist li',
                        '.suggest-item',
                        '[data-city]'
                    ];
                    for (const sel of selectors) {
                        const items = document.querySelectorAll(sel);
                        if (items.length > 0) {
                            items[0].click();
                            return true;
                        }
                    }
                    return false;
                })()"""
            )
            time.sleep(0.3)
            
            # 发送 ESC 键关闭下拉框
            try:
                page.press_key("Escape")
            except Exception:
                pass
            time.sleep(0.3)
        except Exception as e:
            logger.warning(f"输入到达城市失败: {e}")

        # 4. 输入日期
        logger.info(f"输入日期: {date}")
        try:
            # 点击日期输入框
            page.evaluate(
                """(() => {
                    const selectors = [
                        '#fromDate',
                        'input[name="fromDate"]',
                        '.textbox[name="fromDate"]'
                    ];
                    for (const sel of selectors) {
                        const el = document.querySelector(sel);
                        if (el) {
                            el.click();
                            el.focus();
                            return true;
                        }
                    }
                    return false;
                })()"""
            )
            time.sleep(0.3)
            
            # 输入日期
            page.evaluate(
                f"""(() => {{
                    const dateInputs = document.querySelectorAll('#fromDate, input[name="fromDate"]');
                    dateInputs.forEach(el => {{
                        el.value = {json.dumps(date)};
                        el.dispatchEvent(new Event('input', {{ bubbles: true }}));
                        el.dispatchEvent(new Event('change', {{ bubbles: true }}));
                    }});
                    
                    // 关闭日历弹窗
                    document.body.click();
                }})()"""
            )
            time.sleep(0.3)
        except Exception as e:
            logger.warning(f"输入日期失败: {e}")

        # 5. 点击搜索按钮并等待页面导航
        logger.info("点击搜索按钮")
        start_url = page.evaluate("window.location.href")
        logger.debug(f"当前URL: {start_url}")
        
        try:
            clicked = page.evaluate(
                """(() => {
                    const selectors = [
                        '.btn_search',
                        'button.btn_search',
                        '.search-btn',
                        '#searchBtn'
                    ];
                    for (const sel of selectors) {
                        const btn = document.querySelector(sel);
                        if (btn) {
                            btn.click();
                            return true;
                        }
                    }
                    return false;
                })()"""
            )
            if not clicked:
                logger.error("未找到搜索按钮")
        except Exception as e:
            logger.error(f"点击搜索按钮失败: {e}")
        
        # 等待页面导航到结果页
        logger.info("等待页面导航...")
        time.sleep(2)
        
        nav_timeout = 15
        nav_start = time.time()
        navigated = False
        
        while time.time() - nav_start < nav_timeout:
            try:
                current_url = page.evaluate("window.location.href")
                # 检查URL是否变化到搜索结果页
                if "oneway_list" in current_url or current_url != start_url:
                    logger.info(f"页面已导航到: {current_url}")
                    navigated = True
                    break
                time.sleep(0.5)
            except Exception:
                time.sleep(0.5)
        
        if not navigated:
            logger.warning("页面导航超时，尝试继续解析")
        
        # 等待页面加载完成
        time.sleep(3)
        try:
            page.wait_for_load()
        except Exception:
            pass
        
        # 6. 等待结果加载 - 智能等待
        logger.info("等待航班结果加载...")
        time.sleep(2)
        
        # 尝试多种方式等待航班列表出现
        max_wait = 20  # 最大等待20秒
        start_time = time.time()
        flight_found = False
        
        while time.time() - start_time < max_wait:
            try:
                # 检查是否有航班元素或加载完成
                check_result = page.evaluate(
                    """(() => {
                        // 检查各种航班列表选择器
                        const selectors = [
                            '.flight-list', '.flight-item', '.m-flight-item', '.b-airflight',
                            '[data-flight]', '.airflight', '.flightList', '.flight_content',
                            '.flight-card', '.flightCard', '.list-item', '.air-line',
                            '[class*="flight"]', '[class*="Flight"]', '[class*="airline"]'
                        ];
                        
                        for (const sel of selectors) {
                            const el = document.querySelector(sel);
                            if (el) {
                                return { found: true, selector: sel, html_length: el.innerHTML.length };
                            }
                        }
                        
                        // 检查是否有加载中状态
                        const loadingEl = document.querySelector('.loading, .spinner, [class*="loading"], [class*="Loading"]');
                        if (loadingEl) {
                            return { found: false, loading: true };
                        }
                        
                        // 检查是否有无结果提示
                        const noResultEl = document.querySelector('.no-result, .empty-result, [class*="no-result"], [class*="empty"]');
                        if (noResultEl) {
                            return { found: false, noResult: true, text: noResultEl.innerText };
                        }
                        
                        return { found: false, loading: false };
                    })()"""
                )
                
                if check_result:
                    if check_result.get('found'):
                        logger.info(f"找到航班列表: {check_result.get('selector')}")
                        flight_found = True
                        break
                    elif check_result.get('noResult'):
                        logger.warning(f"搜索无结果: {check_result.get('text')}")
                        break
                    elif check_result.get('loading'):
                        logger.debug("页面正在加载中...")
                    
                time.sleep(1)
            except Exception as e:
                logger.debug(f"等待检查异常: {e}")
                time.sleep(1)
        
        if not flight_found:
            logger.warning("等待航班列表超时，尝试解析当前页面")
        
        time.sleep(2)  # 额外等待确保页面稳定

        # 7. 解析结果
        return self._parse_results(page)

    def _parse_results(self, page) -> list[dict]:
        """解析搜索结果"""
        results = []

        # 调试：保存页面HTML
        if DEBUG_SAVE_HTML:
            try:
                html_content = page.evaluate("document.documentElement.outerHTML")
                debug_path = os.path.join(os.getcwd(), "debug_page.html")
                with open(debug_path, "w", encoding="utf-8") as f:
                    f.write(html_content)
                logger.info(f"页面HTML已保存到: {debug_path}")
            except Exception as e:
                logger.warning(f"保存页面HTML失败: {e}")

        # 首先获取页面URL和基本结构信息
        page_info = page.evaluate(
            """(() => {
                const url = window.location.href;
                const title = document.title;
                
                // 检查是否有错误提示
                const errorEl = document.querySelector('.error-msg, .no-result, .empty-result, [class*="error"]');
                const errorMsg = errorEl ? errorEl.innerText : null;
                
