def get_platform_handler(platform: str) -> Optional[PlatformHandler]:
    """获取平台处理器实例

    Args:
        platform: 平台名称 (qunar, ctrip, fliggy, ly)

    Returns:
        平台处理器实例，如果平台不支持则返回 None
